const entityKeys = [
  'crm.sales_reps',
  'crm.accounts',
  'crm.contacts',
  'crm.deals',
  'crm.activities',
  'marketing.campaigns',
  'marketing.leads',
  'billing.invoices',
  'billing.payments',
  'planning.sales_targets',
];

return entityKeys.map((entity_key, index) => ({
  json: {
    entity_key,
    entity_order: index + 1,
    full_sync_requested: true,
  },
}));

const expected = [
  'crm.sales_reps','crm.accounts','crm.contacts','crm.deals','crm.activities',
  'marketing.campaigns','marketing.leads','billing.invoices','billing.payments','planning.sales_targets'
];
const allowedStages = new Set(['no_change_entity_sync_completed','entity_incremental_sync_committed']);
const rows = $input.all().map(i => i.json);
const keys = rows.map(r => r.entity_key);
const uniqueKeys = [...new Set(keys)];
const missing = expected.filter(k => !uniqueKeys.includes(k));
const unexpected = uniqueKeys.filter(k => !expected.includes(k));
const badStages = rows.filter(r => !allowedStages.has(r.workflow_stage)).map(r => ({entity_key:r.entity_key, workflow_stage:r.workflow_stage}));
const all_entities_succeeded = rows.length === 10 && uniqueKeys.length === 10 && missing.length === 0 && unexpected.length === 0 && badStages.length === 0;
return [{json:{
  all_entities_succeeded,
  entity_result_count: rows.length,
  unique_entity_count: uniqueKeys.length,
  committed_entity_count: rows.filter(r => r.workflow_stage === 'entity_incremental_sync_committed').length,
  no_change_entity_count: rows.filter(r => r.workflow_stage === 'no_change_entity_sync_completed').length,
  missing_entities: missing,
  unexpected_entities: unexpected,
  invalid_stage_results: badStages,
  entity_results: rows,
  workflow_stage: 'full_sync_entity_batch_validated'
}}];

return [{json:{
  full_sync_succeeded: true,
  reporting_ro_verified: Boolean($json.reporting_ro_verified),
  reporting_deal_count: $json.reporting_deal_count,
  open_deals: $json.open_deals,
  all_open_pipeline: $json.all_open_pipeline,
  dl0392_reporting_amount: $json.dl0392_reporting_amount,
  completed_at: new Date().toISOString(),
  workflow_stage: 'full_multi_entity_sync_and_reporting_verified'
}}];
